reg_decoder_fld_t tof3_tm_pex_pipe_rspec__edf_arb_global_ctrl_fld_list[] = {
    { "edf_pps_shaper_bp_ctrl", 0, 0, 0,0, 
      "Controls behavior of EDF arbiter when the PPS shaper is backpressuring all ports from sending SOPs. 1 = stall SOP EDF counters.  0 = no effect" },
    { "edf_bp_start_val_adj", 2, 1, 0,0, 
      "Adjusted SOP/MOP start value when MGC/MGD backpressures the arbiter.  This accounts for additional buffer space in MGC/MGD. Final adjustment value = edf_arb_spd_ctrl0<inc_amt> * 2^edf_bp_start_val_adj (left-shift). A value of 0 disables this adjustment value" },
    { "mgc_sop_bp_ctrl", 4, 3, 0,0, 
      "0 = Do nothing on backpressure (i.e. continue counting).  1 = Reset EDF SOP counters on MGC/MGD backpressure. 2 = Hold onto current EDF SOP counter value during MGC/MGD backpressure (i.e. stall count). 3 = reserved" },
    { "mgc_mop_bp_ctrl", 6, 5, 0,0, 
      "0 = Do nothing on backpressure (i.e. continue counting).  1 = Reset EDF MOP counters on MGC/MGD backpressure. 2 = Hold onto current EDF MOP counter value during MGC/MGD backpressure (i.e. stall count). 3 = reserved" },
    { "sop_scale_factor", 8, 7, 0,0, 
      "Amount SOP is scaled vs MOP.  0=no scaling, 1=SOP divide by 2, 2=SOP divide by 4, 3=SOP divide by 8" },
    { "edf_arb_disable", 9, 9, 0,0, 
      "Disables EDF arbiter and replaces arbiter with common port-speed aware arbiter" },
};
