reg_decoder_fld_t tof3_mau_unit_ram_addrmap__match_next_table_bitpos_fld_list[] = {
    { "match_next_table1_bitpos", 2, 0, 0,0, 
      "Bit position of next-table1 in match RAM. Next-table1 is the 2nd match entry in the RAM. Bits 1:0 code 1+position, so codes 0 to 7 mean bits 1 to 8 respectively." },
    { "match_next_table2_bitpos", 7, 3, 0,0, 
      "Bit positions of next-table 2 in match RAM. Next-table 2 is the 3rd match entry in the RAM. This is an inner match, which can't combine with other RAMs to do wide matches (next-table 0 and 1 can). The 5 bit field codes 1+position, so codes 0 to 31 mean lst starts at bits 1 to 32 respectively." },
    { "match_next_table3_bitpos", 12, 8, 0,0, 
      "Bit positions of next-table 3 in match RAM. Next-table 3 is the 4th match entry in the RAM. This is an inner match, which can't combine with other RAMs to do wide matches (next-table 0 and 1 can). The 5 bit field codes 1+position, so codes 0 to 31 mean lst starts at bits 1 to 32 respectively." },
    { "match_next_table4_bitpos", 17, 13, 0,0, 
      "Bit positions of next-table 4 in match RAM. Next-table 4 is the 5th match entry in the RAM. This is an inner match, which can't combine with other RAMs to do wide matches (next-table 0 and 1 can). The 5 bit field codes 1+position, so codes 0 to 31 mean lst starts at bits 1 to 32 respectively." },
};
